-- Loan management sample database (loan-management-sample-database) v1 — mysql
-- Synthetic sample data, CC0-1.0. Deterministic: the same spec and seed produce this byte for byte.
-- seed: flagship:loan-management-sample-database:100k
-- Engine 2 (faker 10.6.0), locale en_US. UTF-8.
-- Tables in dependency order; foreign keys are added after the data.

SET NAMES utf8mb4;
START TRANSACTION;

CREATE TABLE `branches` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `city` varchar(40) NOT NULL,
    `code` varchar(6) NOT NULL UNIQUE,
    `name` varchar(40) NOT NULL,
    `phone` varchar(20) NOT NULL,
    `postal_code` varchar(10) NOT NULL,
    `state` varchar(3) NOT NULL
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `branch_targets` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `branch_id` int NOT NULL,
    `collection_target` decimal(14,2) NOT NULL,
    `disbursement_target` decimal(14,2) NOT NULL,
    `target_month` int NOT NULL,
    `target_year` int NOT NULL,
    CONSTRAINT `ck_branch_targets_collection_target` CHECK (`collection_target` BETWEEN 150000 AND 4000000),
    CONSTRAINT `ck_branch_targets_disbursement_target` CHECK (`disbursement_target` BETWEEN 250000 AND 6000000),
    CONSTRAINT `ck_branch_targets_target_month` CHECK (`target_month` BETWEEN 1 AND 12),
    CONSTRAINT `ck_branch_targets_target_year` CHECK (`target_year` BETWEEN 2021 AND 2025)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `collateral_types` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `description` text NOT NULL,
    `name` varchar(15) NOT NULL UNIQUE,
    CONSTRAINT `ck_collateral_types_name` CHECK (`name` IN ('real_estate', 'vehicle', 'equipment', 'inventory', 'savings_deposit', 'securities', 'gold', 'receivables'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `customers` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `address` varchar(101) NOT NULL,
    `city` varchar(40) NOT NULL,
    `date_of_birth` date NOT NULL,
    `email` varchar(78) NOT NULL,
    `employment_status` varchar(13) NOT NULL,
    `first_name` varchar(30) NOT NULL,
    `last_name` varchar(44) NOT NULL,
    `monthly_income` decimal(14,2) NOT NULL,
    `national_id` varchar(12) NOT NULL UNIQUE,
    `phone` varchar(26) NOT NULL,
    `postal_code` varchar(10) NOT NULL,
    `state` varchar(3) NOT NULL,
    CONSTRAINT `ck_customers_employment_status` CHECK (`employment_status` IN ('employed', 'self_employed', 'retired', 'unemployed', 'student')),
    CONSTRAINT `ck_customers_monthly_income` CHECK (`monthly_income` BETWEEN 900 AND 40000)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `credit_scores` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `customer_id` int NOT NULL,
    `evaluation_date` date NOT NULL,
    `provider` varchar(14) NOT NULL,
    `risk_rating` varchar(9) NOT NULL,
    `score` int NOT NULL,
    CONSTRAINT `ck_credit_scores_provider` CHECK (`provider` IN ('bureau_north', 'bureau_central', 'bureau_coastal')),
    CONSTRAINT `ck_credit_scores_risk_rating` CHECK (`risk_rating` IN ('low', 'medium', 'high', 'very_high')),
    CONSTRAINT `ck_credit_scores_score` CHECK (`score` BETWEEN 300 AND 850)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `customer_references` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `customer_id` int NOT NULL,
    `email` varchar(78) NOT NULL,
    `full_name` varchar(62) NOT NULL,
    `phone` varchar(26) NOT NULL,
    `relationship` varchar(9) NOT NULL,
    CONSTRAINT `ck_customer_references_relationship` CHECK (`relationship` IN ('family', 'friend', 'employer', 'colleague', 'landlord'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `departments` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `code` varchar(6) NOT NULL UNIQUE,
    `cost_center` varchar(7) NOT NULL,
    `name` varchar(16) NOT NULL UNIQUE,
    CONSTRAINT `ck_departments_name` CHECK (`name` IN ('lending', 'underwriting', 'collections', 'operations', 'compliance', 'customer_service', 'finance', 'legal'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `employees` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `branch_id` int NOT NULL,
    `department_id` int NOT NULL,
    `email` varchar(78) NOT NULL,
    `first_name` varchar(30) NOT NULL,
    `hire_date` date NOT NULL,
    `job_title` varchar(14) NOT NULL,
    `last_name` varchar(44) NOT NULL,
    `phone` varchar(26) NOT NULL,
    CONSTRAINT `ck_employees_job_title` CHECK (`job_title` IN ('loan_officer', 'credit_analyst', 'underwriter', 'collector', 'branch_manager', 'teller'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `audit_logs` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `action_performed` varchar(6) NOT NULL,
    `employee_id` int NOT NULL,
    `new_values` varchar(8) NOT NULL,
    `old_values` varchar(12),
    `record_id` int NOT NULL,
    `target_table` varchar(19) NOT NULL,
    `timestamp` datetime NOT NULL,
    CONSTRAINT `ck_audit_logs_action_performed` CHECK (`action_performed` IN ('insert', 'update', 'delete')),
    CONSTRAINT `ck_audit_logs_new_values` CHECK (`new_values` IN ('approved', 'closed', 'paid', 'overdue', 'resolved')),
    CONSTRAINT `ck_audit_logs_old_values` CHECK (`old_values` IN ('pending', 'active', 'scheduled', 'under_review', 'open')),
    CONSTRAINT `ck_audit_logs_record_id` CHECK (`record_id` BETWEEN 1 AND 100000),
    CONSTRAINT `ck_audit_logs_target_table` CHECK (`target_table` IN ('loan_applications', 'active_loans', 'payments', 'repayment_schedules', 'customers', 'collaterals'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `fee_types` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `amount_type` varchar(7) NOT NULL,
    `code` varchar(6) NOT NULL UNIQUE,
    `name` varchar(13) NOT NULL UNIQUE,
    `rate_or_value` decimal(14,2) NOT NULL,
    CONSTRAINT `ck_fee_types_amount_type` CHECK (`amount_type` IN ('fixed', 'percent')),
    CONSTRAINT `ck_fee_types_name` CHECK (`name` IN ('origination', 'late_payment', 'processing', 'prepayment', 'documentation', 'insurance', 'valuation', 'legal')),
    CONSTRAINT `ck_fee_types_rate_or_value` CHECK (`rate_or_value` BETWEEN 0.5 AND 250)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `loan_products` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `code` varchar(6) NOT NULL UNIQUE,
    `description` text NOT NULL,
    `interest_rate` decimal(14,2) NOT NULL,
    `interest_type` varchar(8) NOT NULL,
    `maximum_amount` decimal(14,2) NOT NULL,
    `maximum_term_months` int NOT NULL,
    `minimum_amount` decimal(14,2) NOT NULL,
    `minimum_term_months` int NOT NULL,
    `name` varchar(22) NOT NULL UNIQUE,
    CONSTRAINT `ck_loan_products_interest_rate` CHECK (`interest_rate` BETWEEN 3.5 AND 24),
    CONSTRAINT `ck_loan_products_interest_type` CHECK (`interest_type` IN ('fixed', 'variable')),
    CONSTRAINT `ck_loan_products_maximum_amount` CHECK (`maximum_amount` BETWEEN 25000 AND 750000),
    CONSTRAINT `ck_loan_products_maximum_term_months` CHECK (`maximum_term_months` BETWEEN 36 AND 360),
    CONSTRAINT `ck_loan_products_minimum_amount` CHECK (`minimum_amount` BETWEEN 500 AND 10000),
    CONSTRAINT `ck_loan_products_minimum_term_months` CHECK (`minimum_term_months` BETWEEN 6 AND 24),
    CONSTRAINT `ck_loan_products_name` CHECK (`name` IN ('personal_loan', 'auto_loan', 'home_equity', 'small_business', 'student_refinance', 'debt_consolidation', 'mortgage_15_year', 'mortgage_30_year', 'equipment_finance', 'credit_builder', 'bridge_loan', 'green_home_improvement'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `loan_applications` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `application_date` date NOT NULL,
    `assigned_officer_id` int NOT NULL,
    `branch_id` int NOT NULL,
    `customer_id` int NOT NULL,
    `loan_product_id` int NOT NULL,
    `requested_amount` decimal(14,2) NOT NULL,
    `requested_term_months` int NOT NULL,
    `status` varchar(12) NOT NULL,
    CONSTRAINT `ck_loan_applications_requested_amount` CHECK (`requested_amount` BETWEEN 1000 AND 400000),
    CONSTRAINT `ck_loan_applications_requested_term_months` CHECK (`requested_term_months` BETWEEN 6 AND 84),
    CONSTRAINT `ck_loan_applications_status` CHECK (`status` IN ('submitted', 'under_review', 'approved', 'rejected', 'withdrawn'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `active_loans` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `application_id` int NOT NULL,
    `branch_id` int NOT NULL,
    `customer_id` int NOT NULL,
    `end_date` date NOT NULL,
    `interest_rate` decimal(14,2) NOT NULL,
    `loan_product_id` int NOT NULL,
    `officer_id` int NOT NULL,
    `principal_amount` decimal(14,2) NOT NULL,
    `start_date` date NOT NULL,
    `status` varchar(11) NOT NULL,
    `term_months` int NOT NULL,
    CONSTRAINT `ck_active_loans_interest_rate` CHECK (`interest_rate` BETWEEN 3.5 AND 24),
    CONSTRAINT `ck_active_loans_principal_amount` CHECK (`principal_amount` BETWEEN 1000 AND 400000),
    CONSTRAINT `ck_active_loans_status` CHECK (`status` IN ('active', 'closed', 'defaulted', 'written_off')),
    CONSTRAINT `ck_active_loans_term_months` CHECK (`term_months` BETWEEN 6 AND 84)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `application_documents` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `application_id` int NOT NULL,
    `document_type` varchar(15) NOT NULL,
    `file_name` varchar(16) NOT NULL,
    `file_path` varchar(28) NOT NULL,
    `upload_date` datetime NOT NULL,
    `verification_status` varchar(8) NOT NULL,
    `verified_by` int NOT NULL,
    CONSTRAINT `ck_application_documents_document_type` CHECK (`document_type` IN ('id_card', 'pay_stub', 'bank_statement', 'tax_return', 'utility_bill', 'collateral_deed')),
    CONSTRAINT `ck_application_documents_verification_status` CHECK (`verification_status` IN ('pending', 'verified', 'rejected'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `application_reviews` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `application_id` int NOT NULL,
    `comments` text NOT NULL,
    `decision` varchar(8) NOT NULL,
    `review_date` datetime NOT NULL,
    `reviewer_id` int NOT NULL,
    CONSTRAINT `ck_application_reviews_decision` CHECK (`decision` IN ('approved', 'rejected', 'referred'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `collaterals` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `application_id` int NOT NULL,
    `collateral_type_id` int NOT NULL,
    `description` text NOT NULL,
    `estimated_value` decimal(14,2) NOT NULL,
    `valuation_date` date NOT NULL,
    `valuer_name` varchar(62) NOT NULL,
    `verification_status` varchar(8) NOT NULL,
    CONSTRAINT `ck_collaterals_estimated_value` CHECK (`estimated_value` BETWEEN 2000 AND 900000),
    CONSTRAINT `ck_collaterals_verification_status` CHECK (`verification_status` IN ('pending', 'verified', 'rejected'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `delinquencies` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `days_past_due` int NOT NULL,
    `last_checked_date` datetime NOT NULL,
    `loan_id` int NOT NULL,
    `overdue_interest` decimal(14,2) NOT NULL,
    `overdue_principal` decimal(14,2) NOT NULL,
    `status` varchar(13) NOT NULL,
    CONSTRAINT `ck_delinquencies_days_past_due` CHECK (`days_past_due` BETWEEN 1 AND 365),
    CONSTRAINT `ck_delinquencies_overdue_interest` CHECK (`overdue_interest` BETWEEN 1 AND 9000),
    CONSTRAINT `ck_delinquencies_overdue_principal` CHECK (`overdue_principal` BETWEEN 20 AND 60000),
    CONSTRAINT `ck_delinquencies_status` CHECK (`status` IN ('open', 'in_collection', 'legal', 'resolved'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `collections` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `collector_id` int NOT NULL,
    `contact_date` datetime NOT NULL,
    `contact_method` varchar(11) NOT NULL,
    `delinquency_id` int NOT NULL,
    `outcome_notes` text NOT NULL,
    `promise_amount` decimal(14,2) NOT NULL,
    `promise_to_pay_date` date NOT NULL,
    CONSTRAINT `ck_collections_contact_method` CHECK (`contact_method` IN ('phone', 'sms', 'email', 'letter', 'field_visit')),
    CONSTRAINT `ck_collections_promise_amount` CHECK (`promise_amount` BETWEEN 50 AND 5000)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `disbursements` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `account_number` varchar(10) NOT NULL,
    `amount` decimal(14,2) NOT NULL,
    `approved_by` int NOT NULL,
    `bank_name` varchar(114) NOT NULL,
    `disbursement_date` date NOT NULL,
    `loan_id` int NOT NULL,
    `transaction_reference` varchar(14) NOT NULL UNIQUE,
    CONSTRAINT `ck_disbursements_amount` CHECK (`amount` BETWEEN 1000 AND 400000)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `guarantors` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `annual_income` decimal(14,2) NOT NULL,
    `application_id` int NOT NULL,
    `email` varchar(78) NOT NULL,
    `first_name` varchar(30) NOT NULL,
    `last_name` varchar(44) NOT NULL,
    `national_id` varchar(12) NOT NULL UNIQUE,
    `phone` varchar(26) NOT NULL,
    `relationship` varchar(16) NOT NULL,
    CONSTRAINT `ck_guarantors_annual_income` CHECK (`annual_income` BETWEEN 18000 AND 450000),
    CONSTRAINT `ck_guarantors_relationship` CHECK (`relationship` IN ('spouse', 'parent', 'sibling', 'friend', 'business_partner'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `insurance_policies` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `coverage_amount` decimal(14,2) NOT NULL,
    `end_date` date NOT NULL,
    `loan_id` int NOT NULL,
    `policy_number` varchar(14) NOT NULL UNIQUE,
    `premium_amount` decimal(14,2) NOT NULL,
    `provider_name` varchar(114) NOT NULL,
    `start_date` date NOT NULL,
    CONSTRAINT `ck_insurance_policies_coverage_amount` CHECK (`coverage_amount` BETWEEN 1000 AND 400000),
    CONSTRAINT `ck_insurance_policies_premium_amount` CHECK (`premium_amount` BETWEEN 40 AND 2500)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `legal_actions` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `action_type` varchar(13) NOT NULL,
    `case_number` varchar(14) NOT NULL UNIQUE,
    `court_name` varchar(18) NOT NULL,
    `current_status` varchar(16) NOT NULL,
    `expense_incurred` decimal(14,2) NOT NULL,
    `filing_date` date NOT NULL,
    `loan_id` int NOT NULL,
    CONSTRAINT `ck_legal_actions_action_type` CHECK (`action_type` IN ('demand_letter', 'lawsuit', 'judgment', 'settlement', 'repossession')),
    CONSTRAINT `ck_legal_actions_court_name` CHECK (`court_name` IN ('Circuit Court', 'District Court', 'County Court', 'Superior Court', 'Small Claims Court')),
    CONSTRAINT `ck_legal_actions_current_status` CHECK (`current_status` IN ('filed', 'in_progress', 'judgment_entered', 'settled', 'dismissed')),
    CONSTRAINT `ck_legal_actions_expense_incurred` CHECK (`expense_incurred` BETWEEN 150 AND 25000)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `loan_fees` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `amount_charged` decimal(14,2) NOT NULL,
    `charge_date` date NOT NULL,
    `fee_type_id` int NOT NULL,
    `is_paid` tinyint(1) NOT NULL,
    `loan_id` int NOT NULL,
    CONSTRAINT `ck_loan_fees_amount_charged` CHECK (`amount_charged` BETWEEN 5 AND 2500)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `loan_reschedules` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `approval_date` date NOT NULL,
    `approved_by` int NOT NULL,
    `loan_id` int NOT NULL,
    `new_interest_rate` decimal(14,2) NOT NULL,
    `new_term_months` int NOT NULL,
    `reason` text NOT NULL,
    `request_date` date NOT NULL,
    CONSTRAINT `ck_loan_reschedules_new_interest_rate` CHECK (`new_interest_rate` BETWEEN 2.5 AND 20),
    CONSTRAINT `ck_loan_reschedules_new_term_months` CHECK (`new_term_months` BETWEEN 12 AND 120)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `payment_methods` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `code` varchar(5) NOT NULL UNIQUE,
    `is_active` tinyint(1) NOT NULL,
    `name` varchar(13) NOT NULL UNIQUE,
    CONSTRAINT `ck_payment_methods_name` CHECK (`name` IN ('bank_transfer', 'direct_debit', 'debit_card', 'credit_card', 'cash', 'check'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `payments` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `amount_paid` decimal(14,2) NOT NULL,
    `collected_by` int NOT NULL,
    `loan_id` int NOT NULL,
    `payment_date` datetime NOT NULL,
    `payment_method_id` int NOT NULL,
    `transaction_reference` varchar(16) NOT NULL UNIQUE,
    CONSTRAINT `ck_payments_amount_paid` CHECK (`amount_paid` BETWEEN 20 AND 8000)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `repayment_schedules` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `due_date` date NOT NULL,
    `fees_due` decimal(14,2) NOT NULL,
    `installment_number` int NOT NULL,
    `interest_due` decimal(14,2) NOT NULL,
    `loan_id` int NOT NULL,
    `principal_due` decimal(14,2) NOT NULL,
    `status` varchar(14) NOT NULL,
    `total_due` decimal(14,2) NOT NULL,
    CONSTRAINT `ck_repayment_schedules_fees_due` CHECK (`fees_due` BETWEEN 0 AND 35),
    CONSTRAINT `ck_repayment_schedules_installment_number` CHECK (`installment_number` BETWEEN 1 AND 84),
    CONSTRAINT `ck_repayment_schedules_interest_due` CHECK (`interest_due` BETWEEN 1 AND 1500),
    CONSTRAINT `ck_repayment_schedules_principal_due` CHECK (`principal_due` BETWEEN 20 AND 6000),
    CONSTRAINT `ck_repayment_schedules_status` CHECK (`status` IN ('scheduled', 'paid', 'partially_paid', 'overdue', 'waived'))
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `payment_allocations` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `fees_paid` decimal(14,2) NOT NULL,
    `interest_paid` decimal(14,2) NOT NULL,
    `payment_id` int NOT NULL,
    `penalty_paid` decimal(14,2) NOT NULL,
    `principal_paid` decimal(14,2) NOT NULL,
    `schedule_id` int NOT NULL,
    CONSTRAINT `ck_payment_allocations_fees_paid` CHECK (`fees_paid` BETWEEN 0 AND 35),
    CONSTRAINT `ck_payment_allocations_interest_paid` CHECK (`interest_paid` BETWEEN 0 AND 1500),
    CONSTRAINT `ck_payment_allocations_penalty_paid` CHECK (`penalty_paid` BETWEEN 0 AND 120),
    CONSTRAINT `ck_payment_allocations_principal_paid` CHECK (`principal_paid` BETWEEN 10 AND 6000)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `penalties` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `amount_charged` decimal(14,2) NOT NULL,
    `charge_date` date NOT NULL,
    `is_paid` tinyint(1) NOT NULL,
    `loan_id` int NOT NULL,
    `reason` text NOT NULL,
    `schedule_id` int NOT NULL,
    CONSTRAINT `ck_penalties_amount_charged` CHECK (`amount_charged` BETWEEN 10 AND 500)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE `write_offs` (
    `id` int NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `approved_by` int NOT NULL,
    `interest_written_off` decimal(14,2) NOT NULL,
    `loan_id` int NOT NULL,
    `principal_written_off` decimal(14,2) NOT NULL,
    `reason` text NOT NULL,
    `write_off_date` date NOT NULL,
    CONSTRAINT `ck_write_offs_interest_written_off` CHECK (`interest_written_off` BETWEEN 10 AND 40000),
    CONSTRAINT `ck_write_offs_principal_written_off` CHECK (`principal_written_off` BETWEEN 100 AND 250000)
) DEFAULT CHARSET=utf8mb4;































